package com.nazril.asisten;

import android.app.Activity;
import android.content.ActivityNotFoundException;
import android.content.Intent;
import android.media.projection.MediaProjectionManager;
import android.net.Uri;
import android.os.Build;
import android.os.Bundle;
import android.webkit.JavascriptInterface;
import android.webkit.ValueCallback;
import android.webkit.WebChromeClient;
import android.webkit.WebResourceRequest;
import android.webkit.WebResourceResponse;
import android.webkit.WebSettings;
import android.webkit.WebView;
import android.webkit.WebViewClient;

import androidx.webkit.WebViewAssetLoader;

public class MainActivity extends Activity {

    private static final int REQ_FILE_CHOOSER = 1;
        private static final int REQ_SCREEN_CAPTURE = 1001;

            private WebView w;
                private ValueCallback<Uri[]> cb;
                    private WebViewAssetLoader loader;
                        private MediaProjectionManager projectionManager;

                            @Override
                                protected void onCreate(Bundle b) {
                                        super.onCreate(b);

                                                loader = new WebViewAssetLoader.Builder()
                                                                .addPathHandler("/assets/", new WebViewAssetLoader.AssetsPathHandler(this))
                                                                                .build();

                                                                                        w = new WebView(this);
                                                                                                setContentView(w);

                                                                                                        WebSettings s = w.getSettings();
                                                                                                                s.setJavaScriptEnabled(true);
                                                                                                                        s.setDomStorageEnabled(true);

                                                                                                                                // Jembatan agar JavaScript bisa memanggil Android.startScreenCapture()
                                                                                                                                        w.addJavascriptInterface(this, "Android");

                                                                                                                                                w.setWebViewClient(new WebViewClient() {
                                                                                                                                                            @Override
                                                                                                                                                                        public WebResourceResponse shouldInterceptRequest(WebView v, WebResourceRequest r) {
                                                                                                                                                                                        return loader.shouldInterceptRequest(r.getUrl());
                                                                                                                                                                                                    }
                                                                                                                                                                                                            });

                                                                                                                                                                                                                    w.setWebChromeClient(new WebChromeClient() {
                                                                                                                                                                                                                                @Override
                                                                                                                                                                                                                                            public boolean onShowFileChooser(WebView v, ValueCallback<Uri[]> c,
                                                                                                                                                                                                                                                                                         FileChooserParams p) {
                                                                                                                                                                                                                                                                                                         if (cb != null) cb.onReceiveValue(null);
                                                                                                                                                                                                                                                                                                                         cb = c;
                                                                                                                                                                                                                                                                                                                                         try {
                                                                                                                                                                                                                                                                                                                                                             startActivityForResult(p.createIntent(), REQ_FILE_CHOOSER);
                                                                                                                                                                                                                                                                                                                                                                             } catch (ActivityNotFoundException e) {
                                                                                                                                                                                                                                                                                                                                                                                                 cb = null;
                                                                                                                                                                                                                                                                                                                                                                                                                     return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                     return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                         });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 w.loadUrl("https://appassets.androidplatform.net/assets/index.html");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         // Dipanggil dari JavaScript: Android.startScreenCapture()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             @JavascriptInterface
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 public void startScreenCapture() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         runOnUiThread(() -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     projectionManager = (MediaProjectionManager)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         getSystemService(MEDIA_PROJECTION_SERVICE);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     startActivityForResult(projectionManager.createScreenCaptureIntent(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         REQ_SCREEN_CAPTURE);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         @Override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             protected void onActivityResult(int rc, int res, Intent d) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     super.onActivityResult(rc, res, d);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (rc == REQ_FILE_CHOOSER) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (cb != null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         cb.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(res, d));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         cb = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (rc == REQ_SCREEN_CAPTURE) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (res == RESULT_OK && d != null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             Intent svc = new Intent(this, AssistService.class);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             svc.putExtra("resultCode", res);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             svc.putExtra("data", d);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (Build.VERSION.SDK_INT >= 26) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 startForegroundService(svc);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     startService(svc);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 w.evaluateJavascript("onScreenCaptureDenied()", null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             @Override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 public void onBackPressed() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (w.canGoBack()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     w.goBack();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         super.onBackPressed();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }